package proxy

import (
	"net/http"
	"strconv"
)

// writeSyntheticResponse frames a complete body generated by Pipelock before
// committing headers. EOF readers can finish even while outcome storage blocks.
// RFC 9110 permits HEAD to carry the corresponding GET representation's length;
// net/http suppresses its body. Informational, 204 and 304 responses have no body.
// Upstream streams must not use this helper: their final length is not known.
func writeSyntheticResponse(w http.ResponseWriter, status int, body []byte) (int, error) {
	if status < http.StatusOK || status == http.StatusNoContent || status == http.StatusNotModified {
		w.Header().Del("Transfer-Encoding")
		w.Header().Del("Content-Length")
		w.WriteHeader(status)
		return 0, nil
	}
	w.Header().Del("Transfer-Encoding")
	w.Header().Set("Content-Length", strconv.Itoa(len(body)))
	w.WriteHeader(status)
	return w.Write(body)
}

// writeHTTPError retains http.Error's headers and newline while framing its
// complete diagnostic body before the response is committed.
func writeHTTPError(w http.ResponseWriter, message string, status int) {
	http.Error(&syntheticErrorWriter{ResponseWriter: w}, message, status)
}

type syntheticErrorWriter struct {
	http.ResponseWriter
	status int
}

// WriteHeader records the status without committing the buffered diagnostic.
func (w *syntheticErrorWriter) WriteHeader(status int) { w.status = status }

// Write frames the complete diagnostic body before forwarding it.
func (w *syntheticErrorWriter) Write(body []byte) (int, error) {
	return writeSyntheticResponse(w.ResponseWriter, w.status, body)
}
